CREATE TABLE IF NOT EXISTS food_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT NOT NULL, food_id UUID REFERENCES food_catalog(id) ON DELETE SET NULL, food_name TEXT NOT NULL, meal TEXT NOT NULL CHECK (meal IN ('Breakfast','Lunch','Dinner','Snacks')), quantity NUMERIC NOT NULL DEFAULT 1 CHECK (quantity > 0), grams NUMERIC NOT NULL DEFAULT 100, calories NUMERIC NOT NULL DEFAULT 0, protein NUMERIC NOT NULL DEFAULT 0, carbs NUMERIC NOT NULL DEFAULT 0, fat NUMERIC NOT NULL DEFAULT 0, fiber NUMERIC NOT NULL DEFAULT 0, log_date DATE NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now())